      border: 0;
    }
  </style>
</head>
<body>
  <main id="root"></main>

  <script type="text/babel">
    const { useState, useRef, useEffect } = React;

    function ContactForm() {
      const [formData, setFormData] = useState({
        name: '',
        email: '',
        phone: ''
      });

      const [errors, setErrors] = useState({});
      const [submitted, setSubmitted] = useState(false);
      const firstInvalidFieldRef = useRef(null);

      const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));

        // Clear error when user starts typing to correct it
        if (errors[name]) {
          setErrors(prev => ({ ...prev, [name]: undefined }));
        }
      };

      const validate = () => {
        const newErrors = {};

        if (!formData.name.trim()) {
          newErrors.name = 'Error: Full name is required.';
        }

        if (!formData.email.trim()) {
          newErrors.email = 'Error: Email address is required.';
        } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
          newErrors.email = 'Error: Enter a valid email like name@example.com.';
        }

        if (formData.phone && !/^\+?[0-9\s\-\(\)]+$/.test(formData.phone)) {
          newErrors.phone = 'Error: Phone number format is invalid. Example: +1 (555) 123-4567';
        }

        return newErrors;
      };

      const handleSubmit = (e) => {
        e.preventDefault();
        const newErrors = validate();

        if (Object.keys(newErrors).length > 0) {
          setErrors(newErrors);

          // Focus first invalid field after state update
          setTimeout(() => {
            const firstInvalid = document.querySelector('[aria-invalid="true"]');
            if (firstInvalid) {
              firstInvalid.focus();
            }
          }, 0);
        } else {
          setSubmitted(true);
          setErrors({});
          // Note: In a real app, send data to the server here.
        }
      };

      if (submitted) {
        return (
          <div className="container" role="status" aria-live="polite">
            <h1>Message Sent</h1>
            <p>Thank you for reaching out! Our support team will contact you soon.</p>
            <button type="button" onClick={() => { setSubmitted(false); setFormData({name: '', email: '', phone: ''}); }}>
              Send another message
            </button>
          </div>
        );
      }

      return (
        <div className="container">
          <h1>Contact Support</h1>
          <p className="subtitle">How can we help you today?</p>

          <form onSubmit={handleSubmit} noValidate>
            <div className="form-field">
              <label htmlFor="name">
                Full name 
                <span className="required-marker" aria-hidden="true">*</span>
                <span className="visually-hidden">required</span>
              </label>
              <input
                id="name"
                name="name"
                type="text"
                required
                autoComplete="name"
                value={formData.name}
                onChange={handleChange}
                aria-invalid={!!errors.name}
                aria-describedby={errors.name ? "name-error" : undefined}
              />
              {errors.name && <p id="name-error" className="error-text">{errors.name}</p>}
            </div>

            <div className="form-field">
              <label htmlFor="email">
                Email address 
                <span className="required-marker" aria-hidden="true">*</span>
                <span className="visually-hidden">required</span>
              </label>
              <input
                id="email"
                name="email"
                type="email"
                required
                autoComplete="email"
                value={formData.email}
                onChange={handleChange}
                aria-invalid={!!errors.email}
                aria-describedby={errors.email ? "email-error" : undefined}
              />
              {errors.email && <p id="email-error" className="error-text">{errors.email}</p>}
            </div>

            <div className="form-field">
              <label htmlFor="phone">Phone number</label>
              <input
                id="phone"
                name="phone"
                type="tel"
                autoComplete="tel"
                value={formData.phone}
                onChange={handleChange}
                aria-invalid={!!errors.phone}
                aria-describedby={errors.phone ? "phone-help phone-error" : "phone-help"}
              />
              <p id="phone-help" className="help-text">Expected format: +1 (555) 123-4567</p>
              {errors.phone && <p id="phone-error" className="error-text">{errors.phone}</p>}
            </div>

            <button type="submit">Submit request</button>
          </form>
        </div>
      );
    }

    const root = ReactDOM.createRoot(document.getElementById('root'));
    root.render(<ContactForm />);
  </script>
</body>
